import React, { useState } from 'react'; // 1. Import useState
import './LoginPage.css';

const LoginPage = () => {
  // 2. Set up state variables
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (event) => {
    // This function prevents the page from reloading
    event.preventDefault();

    // For now, we'll just log the data to the console
    console.log('Login attempt with:', { email, password });

    // Later, we will send this data to the backend API
  };

  return (
    <div className="login-container">
      {/* 4. Connect the submit handler to the form */}
      <form className="login-form" onSubmit={handleSubmit}>
        <h2>Login</h2>
        <div className="input-group">
          <label htmlFor="email">Email</label>
          <input
            type="email"
            id="email"
            name="email"
            required
            value={email} // 3. Connect value to state
            onChange={(e) => setEmail(e.target.value)} // 3. Update state on change
          />
        </div>
        <div className="input-group">
          <label htmlFor="password">Password</label>
          <input
            type="password"
            id="password"
            name="password"
            required
            value={password} // 3. Connect value to state
            onChange={(e) => setPassword(e.target.value)} // 3. Update state on change
          />
        </div>
        <button type="submit" className="login-button">Login</button>
      </form>
    </div>
  );
};

export default LoginPage;
